import com.fasterxml.jackson.databind.JsonNode;
import com.fasterxml.jackson.databind.ObjectMapper;
import java.io.IOException;
import java.io.InputStream;
import java.io.PrintStream;

public final class ClaimOfficeCli {

    private static final ObjectMapper MAPPER = new ObjectMapper();

    private ClaimOfficeCli() {
    }

    public static int run(InputStream in, PrintStream out, PrintStream err) {
        JsonNode scenario;
        try {
            scenario = MAPPER.readTree(in);
        } catch (IOException e) {
            err.println(e.getMessage());
            return 1;
        }
        String results;
        try {
            results = ScenarioJson.results(ScenarioJson.scenarioOf(scenario).settle());
        } catch (RejectedScenario rejected) {
            err.println(rejected.getMessage());
            return 1;
        }
        out.print(results);
        return 0;
    }

    public static void main(String[] args) {
        System.exit(run(System.in, System.out, System.err));
    }
}
===== ClaimResult.java =====
import java.math.BigDecimal;

/**
 * What a claim step paid out, and what is left of the policy's cap.
 *
 * <p>Both amounts are money the MHPCO owes, so both are settled to whole G in
 * the MHPCO's favour when the result is recorded. This is the one place that
 * knows a claim is reported in whole G.
 */
record ClaimResult(int payout, int remainingCap) implements StepResult {

    /**
     * Records a settled claim, taking the fractions the calculation kept down
     * to the whole G the MHPCO reports.
     */
    static ClaimResult of(BigDecimal payout, BigDecimal remainingCap) {
        return new ClaimResult(WholeG.payout(payout), WholeG.payout(remainingCap));
    }
}
===== ClaimStep.java =====
/**
 * A damage report made against a policy an earlier quote created.
 *
 * <p>Working a claim through means settling its incident against the policy it
 * names, and reporting both what was paid out and what is left of that
 * policy's cap afterwards. A claim leaves nothing new in the ledger: it draws
 * down the policy already filed there.
 */
record ClaimStep(int policy, Incident incident) implements Step {

    @Override
    public StepResult settle(Customer customer, int index, ScenarioLedger ledger) {
        Policy written = ledger.policyWrittenBy(policy);
        return ClaimResult.of(written.settle(incident), written.remainingCap());
    }
}
