/**
 * One damaged item in an incident reported to the MHPCO.
 *
 * <p>A damage is what the item lost, so the MHPCO refuses a report of a
 * negative amount outright rather than reading it as a credit in its favour.
 */
record Damage(String itemType, int amount) {

    Damage {
        if (amount < 0) {
            throw new RejectedScenario(
                    "a damage of " + amount + " G to a " + itemType + " is not a damage");
        }
    }
}
===== DamageClause.java =====
import java.math.BigDecimal;

/**
 * The MHPCO's clauses on how much of a damage it reimburses at all, before the
 * deductible is taken off.
 *
 * <p>Damage to a highly enchanted item is reimbursed at only half the damage
 * amount: enchantments are held to be part of the risk the customer brought.
 *
 * <p>The MHPCO also holds that damage to an item of dragon material is fully
 * reimbursed. That clause has no branch here, and deliberately so: full
 * reimbursement is already what this class does when no clause bears on a
 * damage, and wherever the MHPCO has said what happens when both clauses meet,
 * the high-enchantment clause wins. Dragon material therefore never moves a
 * payout, and an item's material is not carried into the domain at all. Should
 * the MHPCO ever let dragon material override the half reimbursement, or
 * recognise a clause that reimburses at less than the full amount, the material
 * would have to be read from the report and a clause added here.
 */
final class DamageClause {

    private static final int HALF_REIMBURSEMENT_FROM_ENCHANTMENT = 8;
    private static final Percentage HALF_REIMBURSEMENT = Percentage.of(50);

    private DamageClause() {
    }

    static BigDecimal reimbursedPartOf(Item damaged, BigDecimal damage) {
        if (isHighlyEnchanted(damaged)) {
            return HALF_REIMBURSEMENT.ofAmount(damage);
        }
        return damage;
    }

    private static boolean isHighlyEnchanted(Item damaged) {
        return damaged.enchantment() >= HALF_REIMBURSEMENT_FROM_ENCHANTMENT;
    }
}
===== DamagedItem.java =====
import java.util.ArrayList;
import java.util.List;

/**
 * One damage entry of an incident together with the insured item it names.
 *
 * <p>A damage entry names its item by type, the way the report is written;
 * what the clauses need is the insured item itself, with its enchantment and
 * its material. Reading the one against the other is what this record carries:
 * the entry and the item it was matched to, so that no later step has to pair
 * them up again.
 *
 * <p>A policy may cover several items of the same type, so each entry is
 * matched to a separate insured item: the MHPCO will not settle the same item
 * twice on one report, and a report naming more items of a type than the
 * policy covers is refused outright.
 *
 * <p>Changes whenever the MHPCO revises how a report is read against a policy;
 * knows nothing about what is reimbursed for the items it finds.
 */
record DamagedItem(Item insured, Damage damage) {

    /**
     * The damage entries of a report, each paired with the insured item it
     * names, in the order they are reported.
     */
    static List<DamagedItem> of(List<Item> insured, List<Damage> damages) {
        List<Item> unclaimed = new ArrayList<>(insured);
        List<DamagedItem> damaged = new ArrayList<>();
        for (Damage damage : damages) {
            damaged.add(new DamagedItem(claim(unclaimed, damage), damage));
        }
        return damaged;
    }

    private static Item claim(List<Item> unclaimed, Damage damage) {
        for (int index = 0; index < unclaimed.size(); index++) {
            if (unclaimed.get(index).type().equals(damage.itemType())) {
                return unclaimed.remove(index);
            }
        }
        throw new RejectedScenario(
                "the policy does not cover a " + damage.itemType() + " for this damage");
    }
}
